import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.DzvPB4Y-.js";const h=JSON.parse('{"title":"2D Packing · BPP2D","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/bpp2d/index.md","filePath":"frameworks/bpp2d/index.md"}'),o={name:"frameworks/bpp2d/index.md"};function r(d,e,s,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_2d-packing-·-bpp2d" tabindex="-1">2D Packing · BPP2D <a class="header-anchor" href="#_2d-packing-·-bpp2d" aria-label="Permalink to &quot;2D Packing · BPP2D&quot;">​</a></h1><p>Place existing rectangular parts on sheets, validate rotation, spacing, bounds and overlap, then inspect material consumption and remnants. A layout needs demand coverage, sheet-type selection and final validation, not just coordinates.</p><h2 id="minimum-vocabulary" tabindex="-1">Minimum Vocabulary <a class="header-anchor" href="#minimum-vocabulary" aria-label="Permalink to &quot;Minimum Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>API</th><th>Input or output</th></tr></thead><tbody><tr><td>Item</td><td><code>ActualItem</code></td><td>Shape, weight and rotation permission</td></tr><tr><td>Sheet type</td><td><code>SheetType</code></td><td>Dimensions, load capacity and type identity</td></tr><tr><td>Layout candidate</td><td><code>Layer</code></td><td>Placements carrying a sheet type</td></tr><tr><td>Generation request</td><td><code>Bpp2dLayerGenerationRequest</code></td><td>Items, sheet types, spacing and candidate limits</td></tr><tr><td>Application service</td><td><code>ColumnGenerationApplicationService</code></td><td>Generation, assignment, packing and KPI/render output</td></tr></tbody></table><p>Rectangles support optional 90-degree rotation. Circles and mixed shapes come later. Interior intersection is overlap; touching is not. Distinguish actual area from bounding area.</p><h2 id="entry-points" tabindex="-1">Entry Points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry Points&quot;">​</a></h2><p>Both languages expose <code>ColumnGenerationApplicationService</code>, but Kotlin solver injection differs from Rust&#39;s RMP/final executors. A Rust run without solvers is not a completed integer optimization.</p><p>Understand candidate layers and final geometry validation before connecting restricted-master solves, pricing and final MILP. Do not duplicate the framework&#39;s geometry rules in your application workflow.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>Geometric feasibility is not guillotine manufacturability. See <a href="./../csp2d/">CSP2D</a> for production demand, cut trees and coil consumption.</li><li>Circle utilization uses actual circle area, not its bounding rectangle.</li><li>Area consumption, sheet count and type cost are different objectives. A weighted sum is not automatically strict lexicographic optimization.</li><li>Candidate generation or mock execution alone is neither a native solver run nor a full-problem optimality proof.</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><ol><li>Complete <a href="./../setup.html">environment setup</a>.</li><li>Follow <a href="./first-layout.html">your first 2D layout</a> using rectangles and one sheet type.</li><li>Change rotation and spacing, then add multiple types and costs. Inject new generators instead of copying the solving loop.</li><li>Decide whether a new rule constrains one candidate or the combination of selected candidates.</li></ol><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp2d/README.md" target="_blank" rel="noreferrer">Kotlin API and shape capabilities</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp2d/README.md" target="_blank" rel="noreferrer">Rust API and executor contracts</a></li></ul><p><a href="./../">Back to scenario selection</a></p><h2 id="continue-practicing" tabindex="-1">Continue Practicing <a class="header-anchor" href="#continue-practicing" aria-label="Permalink to &quot;Continue Practicing&quot;">​</a></h2><p>Next: <a href="./business-scenario.html">Sheet Types, Rotation and Spacing</a>. Before adapting the scenario to your application, complete the <a href="./../integration.html">business integration checks</a>.</p>',17)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
